const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define western Brazil region
  const westernBrazil = ee.Geometry.Rectangle([-75, -18, -60, 5]);

  // 2. Load MODIS Monthly Aerosol data
  const aodBand = 'Aerosol_Optical_Depth_Land_Mean';

  // Early period: August 2002-2005
  const earlyCol = ee.ImageCollection('MODIS/006/MOD08_M3')
    .filterDate('2002-08-01', '2005-08-31')
    .filter(ee.Filter.calendarRange(8, 8, 'month'))
    .filterBounds(westernBrazil)
    .select(aodBand);

  const earlySize = earlyCol.size().getInfo();
  console.log('Early period images (2002-2005 Aug):', earlySize);

  if (earlySize === 0) {
    console.log('No data for early period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Late period: August 2015-2018
  const lateCol = ee.ImageCollection('MODIS/006/MOD08_M3')
    .filterDate('2015-08-01', '2018-08-31')
    .filter(ee.Filter.calendarRange(8, 8, 'month'))
    .filterBounds(westernBrazil)
    .select(aodBand);

  const lateSize = lateCol.size().getInfo();
  console.log('Late period images (2015-2018 Aug):', lateSize);

  if (lateSize === 0) {
    console.log('No data for late period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Calculate mean AOD for each period
  const earlyMean = earlyCol.mean();
  const lateMean = lateCol.mean();

  // 4. Get statistics
  const earlyStats = earlyMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: westernBrazil,
    scale: 10000,
    maxPixels: 1e9
  });

  const lateStats = lateMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: westernBrazil,
    scale: 10000,
    maxPixels: 1e9
  });

  const earlyAOD = earlyStats.get(aodBand + '_mean').getInfo();
  const earlyCount = earlyStats.get(aodBand + '_count').getInfo();
  const lateAOD = lateStats.get(aodBand + '_mean').getInfo();
  const lateCount = lateStats.get(aodBand + '_count').getInfo();

  console.log('Early period AOD:', earlyAOD, 'Pixels:', earlyCount);
  console.log('Late period AOD:', lateAOD, 'Pixels:', lateCount);

  // 5. Validation
  if (earlyCount === 0 || lateCount === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (earlyAOD === null || lateAOD === null || isNaN(earlyAOD) || isNaN(lateAOD)) {
    console.log('Invalid calculation result.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Check for valid AOD range (typically 0-5)
  if (earlyAOD < 0 || earlyAOD > 10 || lateAOD < 0 || lateAOD > 10) {
    console.log('AOD values out of valid range.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 6. Determine if decrease occurred
  const decrease = earlyAOD - lateAOD;
  console.log('Change (early - late):', decrease.toFixed(4));

  if (decrease > 0) {
    console.log('Aerosol concentration decreased from 2002-2005 to 2015-2018.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Aerosol concentration did not decrease.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
